use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < T > Lock < T > { # [inline (always)] pub fn new (inner : T) -> Self { let (mode , mode_union) = if unlikely (mode :: might_be_dyn_thread_safe ()) { (Mode :: Sync , ModeUnion { sync : ManuallyDrop :: new (RawMutex :: INIT) }) } else { (Mode :: NoSync , ModeUnion { no_sync : ManuallyDrop :: new (Cell :: new (! LOCKED)) }) } ; Lock { mode , mode_union , data : UnsafeCell :: new (inner) } } # [inline (always)] pub fn into_inner (self) -> T { self . data . into_inner () } # [inline (always)] pub fn get_mut (& mut self) -> & mut T { self . data . get_mut () } # [inline (always)] pub fn try_lock (& self) -> Option < LockGuard < '_ , T > > { let mode = self . mode ; match mode { Mode :: NoSync => { let cell = unsafe { & self . mode_union . no_sync } ; let was_unlocked = cell . get () != LOCKED ; if was_unlocked { cell . set (LOCKED) ; } was_unlocked } Mode :: Sync => unsafe { self . mode_union . sync . try_lock () } , } . then (| | LockGuard { lock : self , marker : PhantomData , mode }) } # [doc = " This acquires the lock assuming synchronization is in a specific mode."] # [doc = ""] # [doc = " Safety"] # [doc = " This method must only be called with `Mode::Sync` if `might_be_dyn_thread_safe` was"] # [doc = " true on lock creation."] # [inline (always)] # [track_caller] pub unsafe fn lock_assume (& self , mode : Mode) -> LockGuard < '_ , T > { # [inline (never)] # [track_caller] # [cold] fn lock_held () -> ! { panic ! ("lock was already held") } unsafe { match mode { Mode :: NoSync => { if unlikely (self . mode_union . no_sync . replace (LOCKED) == LOCKED) { lock_held () } } Mode :: Sync => self . mode_union . sync . lock () , } } LockGuard { lock : self , marker : PhantomData , mode } } # [inline (always)] # [track_caller] pub fn lock (& self) -> LockGuard < '_ , T > { unsafe { self . lock_assume (self . mode) } } }
}